import{bQ as e,aL as a,u as r,G as o}from"./chunks/framework.C1gZXFVa.js";const d="/assets/030102.C-yjfQlq.png",m=JSON.parse('{"title":"撤单主流程","description":"平台撮合单笔撤单跨系统时序：用户经网关进委托，查单后调撮合出簿解冻；行情异步推送，不含批量撤与第三方撮合。","frontmatter":{"title":"撤单主流程","description":"平台撮合单笔撤单跨系统时序：用户经网关进委托，查单后调撮合出簿解冻；行情异步推送，不含批量撤与第三方撮合。","head":[["meta",{"name":"keywords","content":"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX"}],["link",{"rel":"canonical","href":"https://tgex.net/pages/070503"}],["meta",{"property":"og:url","content":"https://tgex.net/pages/070503"}],["meta",{"property":"og:title","content":"撤单主流程 · TGEX"}],["meta",{"property":"og:description","content":"平台撮合单笔撤单跨系统时序：用户经网关进委托，查单后调撮合出簿解冻；行情异步推送，不含批量撤与第三方撮合。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://tgex.net/og.jpg"}],["meta",{"name":"twitter:title","content":"撤单主流程 · TGEX"}],["meta",{"name":"twitter:description","content":"平台撮合单笔撤单跨系统时序：用户经网关进委托，查单后调撮合出簿解冻；行情异步推送，不含批量撤与第三方撮合。"}],["meta",{"name":"twitter:image","content":"https://tgex.net/og.jpg"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"TechArticle\\",\\"headline\\":\\"撤单主流程\\",\\"description\\":\\"平台撮合单笔撤单跨系统时序：用户经网关进委托，查单后调撮合出簿解冻；行情异步推送，不含批量撤与第三方撮合。\\",\\"keywords\\":\\"开源交易所,交易所开源,交易所源码,开源交易所源码,商业源码,交易所商业源码,数字货币交易所,加密货币交易所,虚拟货币交易所,区块链交易所,撮合引擎,开发撮合引擎,开源撮合引擎,订单簿,现货交易,现货交易所,合约交易,永续合约,合约交易所,期权交易,加密期权,开源OTC,OTC交易,场外交易,法币交易,区块链钱包,数字货币钱包,充值提现,多商户交易所,交易所架构,交易所设计,交易系统设计,资金清算,资产账务,风控系统,行情推送,WebSocket行情,TGEX\\",\\"url\\":\\"https://tgex.net/pages/070503\\",\\"mainEntityOfPage\\":\\"https://tgex.net/pages/070503\\",\\"inLanguage\\":\\"zh-CN\\",\\"isPartOf\\":{\\"@type\\":\\"WebSite\\",\\"name\\":\\"TGEX\\",\\"url\\":\\"https://tgex.net/\\"},\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"TGEX\\",\\"logo\\":{\\"@type\\":\\"ImageObject\\",\\"url\\":\\"https://tgex.net/logo.svg\\"}},\\"image\\":\\"https://tgex.net/og.jpg\\"}"]]},"headers":[],"relativePath":"pages/070503.md","filePath":"07.现货手册/05.核心流程/03.撤单主流程.md"}'),n={name:"pages/070503.md"};function p(s,t,i,h,l,g){return a(),r("div",null,[...t[0]||(t[0]=[o('<div class="doc-eyebrow">现货手册 · 核心交易流程 / TGEX KNOWLEDGE BASE</div><h1 id="撤单主流程" tabindex="-1">撤单主流程 <a class="header-anchor" href="#撤单主流程" aria-label="Permalink to &quot;撤单主流程&quot;">​</a></h1><div class="doc-lead">单笔撤单沿时序：用户 / 机器人 → 应用网关 → 委托系统 → 撮合系统；查到仍可撤的单后出簿解冻并置为已撤销。同步成功表示撮合侧已落定；深度变化由行情系统异步推送。</div><p align="center"><img src="'+d+'" alt="撤单主流程时序"></p><p>本文假定服务已起来、交易对已可接单；以 <strong>平台撮合 · 单笔撤单</strong> 为主路径。下文按上图时序展开。引擎内出簿与解冻与<a href="/pages/070508">撮合主流程 · 撤单</a>同一条处理链；展示侧见<a href="/pages/070509">行情推送流程</a>。</p><h2 id="_1-用户-机器人-→-应用网关" tabindex="-1">1. 用户 / 机器人 → 应用网关 <a class="header-anchor" href="#_1-用户-机器人-→-应用网关" aria-label="Permalink to &quot;1. 用户 / 机器人 → 应用网关&quot;">​</a></h2><p>调用方（App、开放 API、量化机器人等）发起撤单，经应用网关进入委托。</p><p>常见入参：委托编号（或客户端订单号 + 用户）、必要时版本号等。批量撤单、一键撤是并行能力，本文不展开。</p><h2 id="_2-应用网关-→-委托系统" tabindex="-1">2. 应用网关 → 委托系统 <a class="header-anchor" href="#_2-应用网关-→-委托系统" aria-label="Permalink to &quot;2. 应用网关 → 委托系统&quot;">​</a></h2><p>网关只做转发与接入，不在本文展开鉴权细节。请求到达委托撤单接口后，进入同步受理段。</p><h2 id="_3-委托-→-撮合-查当前委托" tabindex="-1">3. 委托 → 撮合：查当前委托 <a class="header-anchor" href="#_3-委托-→-撮合-查当前委托" aria-label="Permalink to &quot;3. 委托 → 撮合：查当前委托&quot;">​</a></h2><p>委托侧向撮合热数据查询这张单是否还在、属于谁、是否仍可撤。</p><table tabindex="0"><thead><tr><th>查不到或不可撤</th><th>结果</th></tr></thead><tbody><tr><td>无此委托</td><td>经网关拒绝（未出簿 / 未解冻）</td></tr><tr><td>已完全成交 / 已撤销</td><td>拒绝（终态不能再撤）</td></tr><tr><td>仍有未成交剩余且状态允许</td><td>继续调撮合「撤单」</td></tr></tbody></table><p>第三方（非平台）撮合交易对另分支，不在本文主路径。</p><h2 id="_4-委托-→-撮合-撤单" tabindex="-1">4. 委托 → 撮合：撤单 <a class="header-anchor" href="#_4-委托-→-撮合-撤单" aria-label="Permalink to &quot;4. 委托 → 撮合：撤单&quot;">​</a></h2><p>可撤时，委托调用撮合撤单。事件进入与下单相同的撮合处理链（同交易对串行），与可能同时到来的成交抢同一剩余量——以引擎内先后结果为准。</p><p>撮合侧在同步路径上完成（亦见<a href="/pages/070508">撮合主流程</a>撤单支）：</p><ol><li>若单仍在订单簿：<strong>出簿</strong>，按剩余量扣深度，从价位队列拿掉</li><li>未成交占用 <strong>冻结 → 可用</strong>（买退计价币，卖退基础币）</li><li>委托置为已撤销，更新 Redis 缓冲，并从委托热数据移除</li></ol><p>解冻发生在出簿时，而不是「点撤单」的客户端瞬间。资金数字见<a href="/pages/0701#complete">业务概述 · 案例</a>。</p><p>撮合回委托：<strong>成功</strong>。含义是撤单在撮合侧已落定。</p><h2 id="_5-同步返回调用方" tabindex="-1">5. 同步返回调用方 <a class="header-anchor" href="#_5-同步返回调用方" aria-label="Permalink to &quot;5. 同步返回调用方&quot;">​</a></h2><p>委托经网关把结果回给用户 / 机器人：</p><table tabindex="0"><thead><tr><th>结果</th><th>含义</th></tr></thead><tbody><tr><td>成功</td><td>撮合侧已出簿（若曾在簿上）、剩余已解冻、委托已撤销</td></tr><tr><td>拒绝</td><td>无单、已终态、或撮合侧判定不可撤</td></tr><tr><td>调撮合超时</td><td>结果未知：先按<a href="/pages/070510">委托查询主流程</a>确认终态，勿重复盲目连点当作多笔新业务</td></tr></tbody></table><p>深度变化不保证出现在撤单同步响应里。</p><h2 id="_6-异步旁路-撮合-→-行情-→-展示" tabindex="-1">6. 异步旁路：撮合 → 行情 → 展示 <a class="header-anchor" href="#_6-异步旁路-撮合-→-行情-→-展示" aria-label="Permalink to &quot;6. 异步旁路：撮合 → 行情 → 展示&quot;">​</a></h2><p>同步响应返回之后（或不阻塞同步等待），撮合将深度变化等事件经消息队列交给行情系统。行情加工盘口等展示数据，再按订阅推给客户端。</p><p>推送只服务展示，<strong>不改</strong>订单与资金的权威结果。断线后应先拉快照再接增量，见<a href="/pages/070509">行情推送流程</a>。</p><h2 id="本文边界" tabindex="-1">本文边界 <a class="header-anchor" href="#本文边界" aria-label="Permalink to &quot;本文边界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对照</th><th>说明</th></tr></thead><tbody><tr><td><a href="/pages/070502">下单主流程</a></td><td>对称：怎么把单送进撮合</td></tr><tr><td><a href="/pages/070508">撮合主流程</a></td><td>引擎内撤单支与下单支同链</td></tr><tr><td><a href="/pages/070510">委托查询主流程</a></td><td>撤前 / 超时后确认单是否仍可撤</td></tr><tr><td><a href="/pages/070509">行情推送流程</a></td><td>展示侧如何推深度变化</td></tr><tr><td><a href="/pages/0701#complete">业务概述 · 案例</a></td><td>资金教学；与成交抢量的语义</td></tr><tr><td>批量 / 第三方撤单</td><td>不展开</td></tr></tbody></table><p>同组：<a href="/pages/070502">下单主流程</a> · <a href="/pages/070508">撮合主流程</a> · <a href="/pages/070510">委托查询主流程</a> · <a href="/pages/070509">行情推送流程</a> · <a href="/pages/0701">业务概述</a></p>',30)])])}const _=e(n,[["render",p]]);export{m as __pageData,_ as default};
